def is_balanced(text):
    counts = {"(": 0, "[": 0, "{": 0}
    closers = {")": "(", "]": "[", "}": "{"}
    for ch in text:
        if ch in counts:
            counts[ch] += 1
        elif ch in closers:
            counts[closers[ch]] -= 1
            if counts[closers[ch]] < 0:
                return False
    return counts["("] == 0 and counts["["] == 0 and counts["{"] == 0
